class DuplicatePathValidator(DepthFirstTraverser):
    """
    Check that no two document paths in the update expression overlap with each other.
    Paths overlap when they are identical or when one path is a sub-path of the other
    (e.g. SET a and SET a.b).
    """

    def __init__(self, expression_attribute_names):
        self.paths = []
        self.expression_attribute_names = expression_attribute_names or {}

    def _processing_map(self):
        return {
            UpdateExpressionSetAction: self.check_for_overlapping_paths,
            UpdateExpressionRemoveAction: self.check_for_overlapping_paths,
            UpdateExpressionAddAction: self.check_for_overlapping_paths,
            UpdateExpressionDeleteAction: self.check_for_overlapping_paths,
        }

    def check_for_overlapping_paths(self, node):
        path = self._path_to_string(node.children[0])
        for existing_path in self.paths:
            if self._paths_overlap(existing_path, path):
                raise OverlappingPathsException(existing_path, path)
        self.paths.append(path)
        return node

    def _path_to_string(self, path_node):
        """Convert an UpdateExpressionPath node to its string representation."""
        path = ""
        for child in path_node.children:
            if isinstance(child, ExpressionAttributeName):
                path += self.expression_attribute_names.get(
                    child.get_attribute_name_placeholder(),
                    child.get_attribute_name_placeholder(),
                )
            elif isinstance(child, ExpressionAttribute):
                path += child.get_attribute_name()
            elif isinstance(child, ExpressionPathDescender):
                path += "."
            elif isinstance(child, ExpressionSelector):
                path += "[{}]".format(child.get_index())
        return path

    @staticmethod
    def _paths_overlap(first_path, second_path):
        if first_path == second_path:
            return True
        return second_path.startswith(first_path + ".") or second_path.startswith(
            first_path + "["
        )


